def load() -> pd.DataFrame:
    import glob
    import pandas as pd

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*'
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f'No files matched glob: {pattern}')

    dfs = []
    for p in paths:
        if p.lower().endswith(('.csv', '.tsv', '.txt')):
            try:
                df = pd.read_csv(p, dtype=str)
            except Exception:
                # fallback common delimiter
                df = pd.read_csv(p, dtype=str, sep='\t')
        elif p.lower().endswith(('.xlsx', '.xls')):
            df = pd.read_excel(p, dtype=str)
        else:
            # try csv as default
            df = pd.read_csv(p, dtype=str)

        df['__source_file'] = p.split('/')[-1]
        dfs.append(df)

    out = pd.concat(dfs, ignore_index=True, sort=False)
    # Normalize column names a bit
    out.columns = [str(c).strip() for c in out.columns]
    return out
